CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, trial_used INTEGER DEFAULT 0, expires INTEGER DEFAULT 0, kicked INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, username TEXT, plan TEXT, price REAL, status TEXT DEFAULT 'new', created INTEGER);
CREATE TABLE IF NOT EXISTS gifts(id INTEGER PRIMARY KEY AUTOINCREMENT, text TEXT, owner TEXT, taken_by INTEGER);
